mapper.select:
select * from ( SELECT a.ecg_id ecgId, a.user_id userId, a.user_name userName, a.age, a.gender, a.result, a.result_desc resultDesc, DATE_FORMAT( a.ecg_start_time, '%Y-%m-%d %H:%i:%s' ) ecgStartTime, DATE_FORMAT( a.ecg_end_time, '%Y-%m-%d %H:%i:%s' ) ecgEndTime, cd.code_name resultLevel , a.mach_sn machSn, a.company_id companyId, a.dept_id deptId, cc.company_name companyName, ccd.dept_name deptName, DATE_FORMAT( a.create_time, '%Y-%m-%d %H:%i:%s' ) createTime, DATE_FORMAT( a.last_modify_date, '%Y-%m-%d %H:%i:%s' ) lastModifyDate, a.last_modify_user_id lastModifyUserId, a.remark FROM cust_user_ecg_short_term a left join comm_base_code_detail cd on cd.code_id=a.result and type_no='CD801' left join comm_company cc on cc.company_id=a.company_id left join comm_dept ccd on ccd.dept_id=a.dept_id )temp where 1=1
and deptId in
#{code}
and DATE_FORMAT(ecgStartTime,'%Y-%m-%d') >= #{tm}
and DATE_FORMAT(ecgStartTime,'%Y-%m-%d') <= #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by ecgId desc
